-- K-Pantry: 과정 사진을 실제로 보여 주는 스텝에 붙인다 (2026-11-02, 실행 보류 — 보관용)
--
-- 왜: 레시피마다 과정 사진 3장(재료 준비 · 조리 중 · 완성)이 무조건 step 1·2·3 행에 붙어 있어서
--     스텝이 4개 이상인 레시피는 완성 사진이 3번 스텝 설명 옆에 나왔다. 103개 레시피의 사진 307장을
--     스텝 제목과 하나씩 대조해 정한 매핑(lib/kpantry/stepImages.ts)을 DB 로 옮긴다.
--     103개 레시피 중 84개의 사진 위치가 바뀌고, 25개 스텝에는 사진이 두 장 붙는다.
--
-- 바뀌는 것:
--   1) pantry_recipe_steps.image_urls text[] 추가 — 스텝당 사진 여러 장(두 장 붙는 스텝 때문).
--   2) 103개 레시피의 image_urls / image_url 을 매핑대로 다시 채운다. image_url 은 image_urls 의 첫 장(호환용).
--   사진 파일·URL 자체는 바꾸지 않는다. 몇 번 실행해도 같은 결과(전체 상태를 덮어쓴다).
--
-- 실행 전에 확인할 것:
--   - 이 스냅샷 이후 레시피·스텝·사진이 바뀌었으면 아래 '실행 전 점검' 결과가 307 이 아니다 → 다시 생성할 것.
--   - 실행 뒤 프론트엔드: lib/kpantry/stepImages.ts 는 사진이 원래 자리(step 1·2·3)에 있을 때만 매핑을 적용하므로
--     실행해도 사진이 두 번 옮겨지지 않는다. 다만 image_url 만 읽는 동안은 두 장 붙은 스텝의 두 번째 사진이 안 보인다.
--     → getRecipeDetail 이 image_urls 를 읽고 StepsSection 이 그것을 쓰도록 바꾼 뒤, stepImages.ts 매핑 표는 지운다.
--
-- 실행 전 점검 (기대값: 307)
--   select count(*) from pantry_recipe_steps where image_url is not null;

begin;

alter table pantry_recipe_steps
  add column if not exists image_urls text[] not null default '{}';

create temp table _step_images (slug text, step_order int, urls text[]) on commit drop;

-- 매핑이 있는 레시피는 먼저 비우고
update pantry_recipe_steps s
   set image_urls = '{}', image_url = null
  from pantry_recipes r
 where s.recipe_id = r.id
   and r.slug in (select distinct slug from _step_images);

-- 매핑대로 채운다
update pantry_recipe_steps s
   set image_urls = v.urls, image_url = v.urls[1]
  from _step_images v
  join pantry_recipes r on r.slug = v.slug
 where s.recipe_id = r.id
   and s.step_order = v.step_order;

-- 사진 307장이 그대로인지 — 아니면 되돌린다
do $$
declare n int;
begin
  select coalesce(sum(cardinality(image_urls)), 0) into n from pantry_recipe_steps;
  if n <> 307 then
    raise exception 'expected 307 step images, got %', n;
  end if;
end $$;

commit;

